add_filter( 'woocommerce_order_get_items', 'perfectpixel_sort_order_items', 10, 3 );

function perfectpixel_sort_order_items( $items, $order, $types ) {
	if ( count( $items ) < 2 || ! in_array( 'line_item', (array) $types, true ) ) {
		return $items;
	}
	$by = '{{order_items_sort_by}}';
	uasort(
		$items,
		function ( $a, $b ) use ( $by ) {
			if ( ! $a instanceof WC_Order_Item_Product || ! $b instanceof WC_Order_Item_Product ) {
				return 0;
			}
			switch ( $by ) {
				case 'sku':
					$pa = $a->get_product();
					$pb = $b->get_product();
					return strnatcasecmp( $pa ? $pa->get_sku() : '', $pb ? $pb->get_sku() : '' );
				case 'qty':
					return $a->get_quantity() <=> $b->get_quantity();
				case 'total':
					return (float) $a->get_total() <=> (float) $b->get_total();
				default:
					return strnatcasecmp( $a->get_name(), $b->get_name() );
			}
		}
	);
	return 'yes' === '{{order_items_sort_desc}}' ? array_reverse( $items, true ) : $items;
}
